/**
 * @summary Create breadcrumbs component
 * @name base
 * @selector .slds-breadcrumb
 * @restrict ol
 * @support dev-ready
 * @variant
 */

.slds-breadcrumb {
  /**
   * @summary Item of the breadcrumb list
   * @selector .slds-breadcrumb__item
   * @restrict .slds-breadcrumb li
   */
  .slds-list__item,
  .slds-breadcrumb__item {
    position: relative;

    &:before {
      content: '\003E';
      position: absolute;
      left: (($spacing-x-small * 0.5) * -1);
    }

    > a {
      display: block;
      padding-top: 0;
      padding-right: var(--slds-c-breadcrumbs-spacing-inline-end, var(--slds-c-breadcrumbs-spacing-inlineend, var(--sds-c-breadcrumbs-spacing-inline-end, $spacing-x-small)));
      padding-bottom: 0;
      padding-left: var(--slds-c-breadcrumbs-spacing-inline-start, var(--slds-c-breadcrumbs-spacing-inlinestart, var(--sds-c-breadcrumbs-spacing-inline-start, $spacing-x-small)));

      &:hover {
        text-decoration: none;
      }
    }

    &:first-child {

      > a {
        /*! @css-var-fallback padding-left */
        --slds-c-breadcrumbs-spacing-inline-start: 0;
      }

      &:before {
        content: '';
      }
    }
  }

  .slds-dropdown-trigger {
    margin-right: var(--slds-c-breadcrumbs-spacing-inline-end, var(--slds-c-breadcrumbs-spacing-inlineend, var(--sds-c-breadcrumbs-spacing-inline-end, $spacing-x-small)));
  }
}

// Lightning Design System 2.264.1
// Styles specific to Kinetic Breadcrumbs
[kx-scope='breadcrumbs-item'][kx-type='underline'] {

  > a {
    position: relative;
    will-change: color, transform;
    transition: transform $kx-duration-normal $kx-ease-out;
    margin-right: var(--sds-c-breadcrumbs-spacing-inline-end, $spacing-x-small);
    margin-left: var(--sds-c-breadcrumbs-spacing-inline-start, $spacing-x-small);
    padding-right: 0;
    padding-left: 0;

    &:active {
      transform: scale(0.95);

      @media (prefers-reduced-motion: reduce) {
        transform: none;
      }
    }
  }

  > a:after {
    will-change: transform-origin, transform;
    content: '';
    position: absolute;
    top: 80%; // CAUTION: magic number, refactor to calc() if line-height and padding props get added to breadcrumbs
    left: 0%;
    height: rem(1px);
    width: 100%;
    background: var(--slds-g-color-brand-base-30, #{$color-brand-dark});
    background-position: left top;
    transform: scaleX(0);
    transform-origin: var(--slds-kx-breadcrumbs-pointer-position-x, 50%) 0;
    transition: transform $kx-duration-normal $kx-ease-out;
  }

  > a:hover:after {
    transform: scaleX(1);
  }

  &:first-child {

    > a {
      margin-left: 0;
    }
  }
}
